package whirlpool

// compressAVX512 runs n blocks through the kernel in
// compress_avx512_amd64.s, generated by internal/genasm; c is vec. It needs
// AVX-512 BW and VBMI and GFNI, which useVec says.
//
//go:noescape
func compressAVX512(h *[8]uint64, p *byte, n int, c *vecConsts)

// hasAVX512BW, hasAVX512VBMI and hasGFNI are generated by amd64.FeatureProbe:
// the processor reports the feature and the operating system saves the
// vector state.
func hasAVX512BW() bool
func hasAVX512VBMI() bool
func hasGFNI() bool

// useVec gates the vector kernel and vecKernel is the kernel it gates; the
// tests clear the gate to reach the scalar kernel, and swap the kernel for a
// Go stand-in to run the dispatch on a processor that lacks the instructions.
var (
	useVec    = hasAVX512BW() && hasAVX512VBMI() && hasGFNI()
	vecKernel = compressAVX512
)

// maxVecBlocks bounds one kernel call: assembly without a frame cannot be
// preempted, so a huge buffer in one call would hold up the garbage
// collector's stop-the-world for its whole duration. 1024 blocks are 64 KiB,
// about 40 microseconds.
const maxVecBlocks = 1024

// compressBlocks runs the whole blocks of p (a multiple of BlockSize bytes)
// through the vector kernel if the processor has it, the scalar one if not.
func compressBlocks(h *[8]uint64, p []byte) {
	if useVec {
		for len(p) > 0 {
			n := min(len(p)/BlockSize, maxVecBlocks)
			vecKernel(h, &p[0], n, &vec)
			p = p[n*BlockSize:]
		}
		return
	}
	for len(p) > 0 {
		compress(h, p[:BlockSize])
		p = p[BlockSize:]
	}
}
